# O(n²): 모든 쌍을 비교
def has_duplicate(arr):
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] == arr[j]:
                return True
    return False

# O(n): set으로 한 번만 순회
def has_duplicate_fast(arr):
    return len(set(arr)) != len(arr)

